<template>
  <PlatformAdminShell title="模型渠道" description="一个渠道保存连接信息，每个模型独立选择协议、能力和使用权限。">
    <template #actions><button class="btn" @click="pluginOpen=true"><Plus :size="13" />导入影策插件</button><button class="btn" @click="protocolOpen = true"><FileJson :size="13" />导入协议</button><button class="btn" @click="load" :disabled="loading"><RefreshCw :size="13" :class="{'animate-spin':loading}" />刷新</button><button class="btn btn-primary" @click="editChannel()"><Plus :size="14" />添加渠道</button></template>
    <p v-if="error" class="channel-error" role="alert">{{ error }}</p>
    <p v-if="routeError" class="channel-error" role="alert">{{ routeError }}</p>
    <section class="default-model-summary" aria-label="默认模型">
      <div v-for="entry in defaultModels" :key="entry.type" class="default-model-card">
        <span><component :is="typeIcon(entry.type)" :size="14" />{{ typeLabel(entry.type) }}默认模型</span>
        <strong>{{ entry.model?.name || entry.model?.model || '未指定' }}</strong>
        <small>{{ entry.model ? entry.channel.name + (defaultUnavailable(entry.model, entry.channel) ? ' · 当前不可用' : '') : '按可用模型优先级选择' }}</small>
      </div>
      <p>默认模型只用于用户尚未选择时；用户须已获该模型授权。已有剧集锁定和手动选择保持不变。</p>
    </section>
    <div class="channel-workspace">
      <aside class="channel-list card"><div class="channel-list-header"><span>服务渠道</span><b>{{ channels.length }}</b></div><label class="channel-search"><Search :size="13" /><input v-model="search" placeholder="搜索渠道" /></label><div class="channel-list-scroll"><button v-for="channel in filteredChannels" :key="channel.id" type="button" :class="['channel-card',{selected:channel.id === selectedId}]" @click="selectChannel(channel.id)"><div class="channel-card-top"><span class="channel-symbol"><Network :size="17" /></span><span :class="['channel-state-dot',{off:!channel.enabled}]" :title="channel.enabled?'已启用':'已停用'"></span></div><strong>{{ channel.name }}</strong><span class="channel-host">{{ channelHost(channel.base_url) }}</span><div class="channel-model-tags"><span v-for="type in ['text','image','video']" :key="type">{{ typeLabel(type) }} <b>{{ (channel.models || []).filter(model=>model.type===type).length }}</b></span></div></button><div v-if="!filteredChannels.length" class="channel-list-empty">{{ loading ? '正在读取…' : search ? '没有匹配渠道' : '添加第一个模型渠道' }}</div></div><footer><LockKeyhole :size="12" /><span>Key 仅保存在服务端</span></footer></aside>
      <section class="channel-content card">
        <template v-if="selected">
          <header class="channel-detail-heading"><div><div class="channel-detail-title"><h2>{{ selected.name }}</h2><span :class="['channel-enabled-chip',{off:!selected.enabled}]"><i></i>{{ selected.enabled?'已启用':'已停用' }}</span></div><p>{{ selected.base_url }}</p><span class="channel-secret-status"><ShieldCheck :size="12" />{{ selected.has_key||selected.has_auth_fields?.length ? '已配置访问凭据' : '尚未配置访问凭据' }}<template v-if="selected.header_names?.length"> · {{ selected.header_names.length }} 个自定义请求头</template></span></div><div class="channel-tools"><button class="btn btn-sm" @click="probe" :disabled="testing"><Loader2 v-if="testing" :size="12" class="animate-spin" /><PlugZap v-else :size="12" />连接检查</button><button class="btn btn-sm" @click="editChannel(selected)"><Pencil :size="12" />编辑</button><button class="btn btn-icon btn-sm channel-delete" @click="removeChannel" title="删除渠道"><Trash2 :size="13" /></button></div></header>
          <div v-if="probeResult" :class="['channel-probe-result',{failed:probeResult.ok===false}]" role="status"><CircleCheck v-if="probeResult.ok!==false" :size="15" /><CircleAlert v-else :size="15" /><span>{{ probeResult.message || (probeResult.ok===false?'连接检查未通过':'服务目录连接正常') }}</span><small>只读检查，不提交生成</small></div>
          <div class="channel-model-toolbar"><div class="channel-type-tabs"><button v-for="type in ['all','text','image','video']" :key="type" :class="{on:activeType===type}" @click="activeType=type">{{ type==='all'?'全部模型':typeLabel(type) }}<span>{{ type==='all'?selectedModels.length:selectedModels.filter(m=>m.type===type).length }}</span></button></div><div class="channel-model-actions"><button class="btn btn-sm" @click="fetchCatalog" :disabled="catalogLoading"><Loader2 v-if="catalogLoading" :size="12" class="animate-spin" /><Download v-else :size="12" />获取型号</button><button class="btn btn-primary btn-sm" @click="editModel()"><Plus :size="13" />添加模型</button></div></div>
          <div class="channel-table-scroll"><table class="channel-table"><thead><tr><th>模型名称 / 上游型号</th><th>类型</th><th>请求协议</th><th>使用范围</th><th>状态</th><th></th></tr></thead><tbody><tr v-for="model in visibleModels" :key="model.id" :data-config-id="model.config_id" :class="{'is-located':model.config_id===linkedConfigId}"><td><strong>{{ model.name || model.model }}</strong><span v-if="model.is_default" class="model-default-badge">{{ typeLabel(model.type) }}默认</span><code>{{ model.model }}</code><small v-if="model.priority > 0">优先级 {{ model.priority }}</small></td><td><span :class="['model-type',model.type]"><component :is="typeIcon(model.type)" :size="11" />{{ typeLabel(model.type) }}</span></td><td><span class="model-protocol-label">{{ protocolName(model.protocol_id) }}</span></td><td class="model-access">{{ model.access==='selected'?`${model.allowed_user_ids?.length || 0} 个指定用户`:'全部用户' }}</td><td><button :class="['channel-toggle',{on:model.enabled}]" role="switch" :aria-checked="!!model.enabled" :aria-label="`${model.enabled?'停用':'启用'}${model.name || model.model}`" @click="toggleModel(model)" :disabled="!!workingModel"><i></i></button></td><td><div class="model-row-actions"><button class="btn btn-sm model-default-action" :title="defaultUnavailable(model) || (model.is_default ? '已是该类型的默认模型' : '设为该类型的默认模型')" :disabled="!!workingModel || model.is_default || !!defaultUnavailable(model)" @click="setDefaultModel(model)">{{ workingModel===model.id ? '保存中…' : model.is_default ? '默认模型' : '设为默认' }}</button><button class="btn btn-icon btn-sm" title="编辑模型" @click="editModel(model)"><Pencil :size="13" /></button><button class="btn btn-icon btn-sm channel-delete" title="删除模型" @click="removeModel(model)"><Trash2 :size="13" /></button></div></td></tr></tbody></table><div v-if="!visibleModels.length" class="channel-model-empty"><span><Layers3 :size="27" /></span><h3>{{ activeType==='all'?'还没有模型':'还没有'+typeLabel(activeType)+'模型' }}</h3><p>获取上游型号后选择对应协议，或手动添加已知型号。</p><button class="btn btn-primary btn-sm" @click="editModel()"><Plus :size="13" />添加模型</button></div></div>
          <footer class="channel-content-footer"><Info :size="13" /><span>目录中出现型号表示服务提供该名称；请求协议和能力配置决定怎样调用。模型启用后才对获准的创作者显示。</span></footer>
        </template>
        <div v-else class="channel-main-empty"><div><Network :size="34" /></div><h2>把你的模型服务接进来</h2><p>填写一个服务地址和 Key，在同一渠道内管理文字、图片和视频模型。</p><button class="btn btn-primary" @click="editChannel()"><Plus :size="14" />添加渠道</button></div>
      </section>
    </div>

    <div v-if="channelOpen" class="overlay channel-drawer-overlay" @click.self="closeChannel"><aside class="channel-editor-drawer" role="dialog" aria-modal="true" aria-labelledby="channel-editor-title"><header><div><span>CONNECTION</span><h2 id="channel-editor-title">{{ channelForm.id?'编辑渠道':'添加渠道' }}</h2><p>连接信息由该渠道下的模型共用。</p></div><button class="btn btn-icon" @click="closeChannel" aria-label="关闭"><X :size="17" /></button></header><form @submit.prevent="saveChannel"><div class="channel-editor-body"><label>渠道名称<input class="input" v-model.trim="channelForm.name" required placeholder="例如：我的统一服务" maxlength="80" /></label><label>API URL<input class="input" v-model.trim="channelForm.base_url" required type="url" placeholder="https://服务地址 或 http://服务端IP:端口" /></label><label>API Key<span>{{ channelForm.id?'留空保留原密钥；服务端不会返回明文密钥。':'填写这家服务自己的访问密钥。' }}</span><input class="input" v-model="channelForm.api_key" type="password" autocomplete="new-password" :placeholder="channelForm.id && selected?.has_key ? '已配置，输入可替换' : '输入 API Key'" /></label><section class="channel-auth-fields"><label>鉴权字段模板<select class="input" v-model="authProtocolId" aria-label="鉴权字段模板"><option value="">通用 API Key</option><option v-for="protocol in authProtocols" :key="protocol.id" :value="protocol.id">{{ protocol.name }}</option></select><span>按协议填写额外鉴权字段。已保存值不回显，留空保留。</span></label><label v-for="field in authFields" :key="field.name">{{ field.label || field.name }}<textarea v-if="field.type==='textarea'" class="input code-input" :aria-label="field.label||field.name" v-model="authValues[field.name]" rows="5" spellcheck="false" autocomplete="off" placeholder="输入新内容可替换，留空保留已保存值"></textarea><input v-else class="input" :aria-label="field.label||field.name" v-model="authValues[field.name]" :type="field.type==='url'?'url':field.secret===false?'text':'password'" autocomplete="new-password" :placeholder="channelForm.id && selected?.has_auth_fields?.includes(field.name)?'已保存；留空保留':field.required?'此协议必填':'可选'" /><span v-if="channelForm.id && selected?.has_auth_fields?.includes(field.name)" class="editor-checkbox"><input type="checkbox" v-model="authClear" :value="field.name" />清除已保存字段</span></label></section><label class="editor-checkbox"><input v-model="channelForm.enabled" type="checkbox" />启用此渠道</label><details><summary>高级连接设置</summary><label>自定义请求头（JSON）<span>仅管理员可配置；已有敏感请求头不回显。留空保留原值，输入 {} 清空。</span><textarea v-model="channelForm.headersText" class="input code-input" rows="6" placeholder='{"X-Custom-Header":"value"}' spellcheck="false"></textarea></label></details><p v-if="editorError" class="channel-error" role="alert">{{ editorError }}</p></div><footer><button type="button" class="btn" @click="closeChannel">取消</button><button class="btn btn-primary" :disabled="saving"><Loader2 v-if="saving" :size="13" class="animate-spin" />{{ saving?'正在保存…':'保存渠道' }}</button></footer></form></aside></div>

    <div v-if="modelOpen" class="overlay channel-drawer-overlay model-dialog-overlay" @click.self="closeModel">
      <section class="channel-editor-drawer model-editor" role="dialog" aria-modal="true" aria-labelledby="model-editor-title">
        <header><div><span>CHANNEL MODEL</span><h2 id="model-editor-title">{{ modelForm.id?'编辑模型':'添加模型' }}</h2><p>{{ selected?.name }} · 独立设置模型协议、能力与使用权限</p></div><button class="btn btn-icon" @click="closeModel" :disabled="savingModel" aria-label="关闭"><X :size="17" /></button></header>
        <form @submit.prevent="saveModel">
          <div class="channel-editor-body">
            <div class="model-basic-grid">
              <label>显示名称<input class="input" v-model.trim="modelForm.name" required placeholder="创作者看到的名称" maxlength="120" /></label>
              <label>上游模型 ID<input class="input code-input" v-model.trim="modelForm.model" required placeholder="按中转站实际型号填写" maxlength="200" /></label>
              <label>模型类型<select aria-label="模型类型" class="input" v-model="modelForm.type" @change="onModelTypeChange"><option value="text">文字</option><option value="image">图片</option><option value="video">视频</option></select></label>
              <label>备选优先级<input class="input" v-model.number="modelForm.priority" type="number" min="0" max="1000000" /><span>没有可用默认模型时，数值高的优先。</span></label>
            </div>
            <ModelProtocolPicker v-model="modelForm.protocol_id" :options="modelProtocols" :kind="modelForm.type" @change="onProtocolChange" />
            <div class="model-access-grid">
              <fieldset class="model-access-field"><legend>使用权限</legend><label class="editor-checkbox"><input v-model="modelForm.enabled" type="checkbox" />启用模型</label><div class="model-access-options"><label><input v-model="modelForm.access" type="radio" value="all" />全部用户</label><label><input v-model="modelForm.access" type="radio" value="selected" />指定用户</label></div><div v-if="modelForm.access==='selected'" class="model-user-list"><label v-for="user in users" :key="user.id"><input v-model="modelForm.allowed_user_ids" type="checkbox" :value="user.id" /><span>{{ user.displayName || user.display_name || user.username }}</span><small>{{ user.username }}</small></label><p v-if="!users.length">还没有用户，请先到“用户与权限”开通账号。</p></div></fieldset>
              <div class="model-choice-note"><Info :size="16" /><div><strong>默认模型与默认参数是两回事</strong><p>保存后可在模型列表点击“设为默认”，分别设置文字、图片、视频默认模型。下方默认参数仅是请求参数预设，不会改变默认模型或覆盖已有选择。</p></div></div>
            </div>
            <ModelCapabilityFields v-model="modelForm.capabilitiesText" :type="modelForm.type" />
            <details><summary>高级：模型能力与默认参数 JSON</summary><div class="model-json-grid"><label>能力配置（JSON）<span>沿用所选协议提供的能力；仅修改已核实的参数。</span><textarea class="input code-input" v-model="modelForm.capabilitiesText" rows="8" spellcheck="false"></textarea></label><label>默认参数（JSON）<span v-if="selectedProtocol?.provider==='custom_json'">仅协议显式引用的 <code v-pre>{{parameters.xxx}}</code> 会写入 JSON 请求；保存其他字段不会自动生效。</span><span v-else-if="modelForm.type==='text'">只发送所选协议声明并适配的文字参数。思考强度、温度与输出上限是否可调，以协议提供的参数定义为准；流程已有显式值优先。</span><span v-else-if="modelForm.type==='image'">按所选协议的参数定义与映射发送图片参数；角色和场景的流程专用尺寸、请求已有值优先。未声明字段不会自动透传。</span><span v-else>按所选协议的参数定义与映射发送视频参数；分镜时长、项目画幅及请求显式值优先。未声明字段不会自动透传。</span><textarea class="input code-input" v-model="modelForm.defaultsText" rows="8" spellcheck="false"></textarea></label></div></details>
            <p v-if="modelError" class="channel-error" role="alert">{{ modelError }}</p>
          </div>
          <footer><button type="button" class="btn" @click="closeModel" :disabled="savingModel">取消</button><button class="btn btn-primary" :disabled="savingModel"><Loader2 v-if="savingModel" :size="13" class="animate-spin" />{{ savingModel?'正在保存…':'保存模型' }}</button></footer>
        </form>
      </section>
    </div>

    <div v-if="catalogOpen" class="overlay channel-drawer-overlay" @click.self="catalogOpen=false"><aside class="channel-editor-drawer" role="dialog" aria-modal="true"><header><div><span>UPSTREAM CATALOG</span><h2>上游型号目录</h2><p>选择型号后配置类型与请求协议，不会自动提交生成。</p></div><button class="btn btn-icon" @click="catalogOpen=false" aria-label="关闭"><X :size="17" /></button></header><div class="channel-editor-body"><label class="catalog-search"><Search :size="14" /><input v-model="catalogSearch" placeholder="搜索型号" /></label><div class="catalog-notice">{{ catalogNotice || '目录仅提供型号名称；请按服务文档选择正确协议。' }}</div><div v-for="item in filteredCatalog" :key="catalogId(item)" class="catalog-row"><span><strong>{{ item.name || item.display_name || catalogId(item) }}</strong><code>{{ catalogId(item) }}</code></span><button class="btn btn-sm" @click="useCatalogModel(item)"><Plus :size="12" />配置</button></div><div v-if="!filteredCatalog.length" class="channel-list-empty">没有匹配的型号</div></div></aside></div>

    <div v-if="protocolOpen" class="overlay channel-drawer-overlay" @click.self="protocolOpen=false"><aside class="channel-editor-drawer" role="dialog" aria-modal="true"><header><div><span>PROTOCOL PROFILE</span><h2>导入协议定义</h2><p>用于已经核实请求与响应格式的自定义图片／视频接口。</p></div><button class="btn btn-icon" @click="protocolOpen=false" aria-label="关闭"><X :size="17" /></button></header><form @submit.prevent="importProtocol"><div class="channel-editor-body"><p class="protocol-hint">支持 JSON 请求、轮询和响应字段映射。素材以 URL 等 JSON 字段传递；multipart 上传、签名与脚本需专用适配器。保存后在模型中选择此协议，不会自动生成或测试。</p><textarea class="input code-input protocol-json" v-model="protocolText" rows="24" spellcheck="false" placeholder='{"id":"custom.video","name":"自定义视频协议","definition":{"type":"video","create":{"method":"POST","path":"/v1/video","body":{"model":"{{model}}","prompt":"{{prompt}}"}},"response":{"result_url":"data.url"}}}'></textarea><p v-if="protocolError" class="channel-error" role="alert">{{ protocolError }}</p></div><footer><button type="button" class="btn" @click="protocolOpen=false">取消</button><button class="btn btn-primary" :disabled="importing">{{ importing?'正在检查…':'检查并保存' }}</button></footer></form></aside></div>
  <div v-if="pluginOpen" class="overlay channel-drawer-overlay" @click.self="pluginOpen=false"><aside class="channel-editor-drawer" role="dialog" aria-modal="true" aria-label="导入影策插件"><header><div><span>YINGCE PLUGIN</span><h2>导入协议插件</h2><p>支持 .yingce-plugin 压缩包和 manifest.json。先校验，再明确导入。</p></div><button class="btn btn-icon" @click="pluginOpen=false" aria-label="关闭"><X :size="17" /></button></header><div class="channel-editor-body"><label>插件文件<input type="file" accept=".yingce-plugin,.json,.zip" @change="choosePlugin" /></label><p class="protocol-hint">插件只增加渠道协议和参数定义，不修改创作 Skill。导入后还需添加渠道、填写鉴权并绑定模型；不会自动发起模型生成。</p><p v-if="pluginError" class="channel-error" role="alert">{{ pluginError }}</p><template v-if="pluginPreview"><h3>{{ pluginPreview.name }} <small>{{ pluginPreview.version }}</small></h3><div v-for="protocol in pluginPreview.providers" :key="protocol.id" class="catalog-row"><span><strong>{{ protocol.name }}</strong><code>{{ protocol.id }} · {{ typeLabel(protocol.type) }}</code></span><span>{{ protocol.executable===false?'不可执行':'可执行' }}</span></div><p v-for="warning in pluginPreview.warnings" :key="warning" class="catalog-notice">{{ warning }}</p><p v-if="pluginPreview.imported" class="catalog-notice">插件已导入，可在模型的“请求协议”中选择。</p></template></div><footer><button class="btn" :disabled="!pluginFile||pluginBusy" @click="importPlugin(true)">校验预览</button><button class="btn btn-primary" :disabled="!pluginFile||!pluginPreview||pluginBusy||pluginPreview.imported" @click="importPlugin(false)">{{ pluginBusy?'正在处理…':'确认导入' }}</button></footer></aside></div></PlatformAdminShell>
</template>
<script setup>
import { computed, nextTick, onBeforeUnmount, onMounted, reactive, ref, watch } from 'vue'
import { Plus, RefreshCw, FileJson, Search, Network, LockKeyhole, ShieldCheck, Pencil, Trash2, PlugZap, Loader2, CircleCheck, CircleAlert, Download, Layers3, Info, X, Type, Image as ImageIcon, Video } from 'lucide-vue-next'
import { toast } from 'vue-sonner'
import PlatformAdminShell from '~/components/PlatformAdminShell.vue'
import ModelCapabilityFields from '~/components/ModelCapabilityFields.vue'
import ModelProtocolPicker from '~/components/ModelProtocolPicker.vue'
import { channelAPI, platformUserAPI } from '~/composables/useApi'
const channels=ref([]),protocols=ref([]),users=ref([]),selectedId=ref(null),search=ref(''),activeType=ref('all'),loading=ref(false),error=ref(''),testing=ref(false),probeResult=ref(null),workingModel=ref(null)
const route=useRoute(),linkedConfigId=ref(null),routeError=ref('')
let routeHandled=false
let alive=true,loadSequence=0
const channelOpen=ref(false),modelOpen=ref(false),saving=ref(false),savingModel=ref(false),editorError=ref(''),modelError=ref(''),catalogOpen=ref(false),catalogLoading=ref(false),catalog=ref([]),catalogSearch=ref(''),catalogNotice=ref(''),protocolOpen=ref(false),protocolText=ref(''),protocolError=ref(''),importing=ref(false)
const channelForm=reactive({id:null,name:'',base_url:'',api_key:'',headersText:'',enabled:true})
const authProtocolId=ref(''),authValues=reactive({}),authClear=ref([]),pluginOpen=ref(false),pluginFile=ref(null),pluginPreview=ref(null),pluginError=ref(''),pluginBusy=ref(false)
const authProtocols=computed(()=>protocols.value.filter(protocol=>protocol.auth_fields?.length)),authFields=computed(()=>protocols.value.find(protocol=>protocol.id===authProtocolId.value)?.auth_fields||[])
const modelForm=reactive({id:null,name:'',model:'',type:'text',protocol_id:'',priority:0,enabled:true,access:'all',allowed_user_ids:[],capabilitiesText:'{}',defaultsText:'{}'})
const selected=computed(()=>channels.value.find(c=>c.id===selectedId.value)),selectedModels=computed(()=>selected.value?.models||[])
const filteredChannels=computed(()=>channels.value.filter(c=>`${c.name} ${c.base_url}`.toLowerCase().includes(search.value.toLowerCase())))
const visibleModels=computed(()=>selectedModels.value.filter(m=>activeType.value==='all'||m.type===activeType.value))
const modelProtocols=computed(()=>protocols.value.filter(p=>p.type===modelForm.type)),selectedProtocol=computed(()=>protocols.value.find(p=>p.id===modelForm.protocol_id))
const typeLabel=type=>({text:'文字',image:'图片',video:'视频'}[type]||type),typeIcon=type=>({text:Type,image:ImageIcon,video:Video}[type]||Layers3)
const protocolName=id=>protocols.value.find(p=>p.id===id)?.name||id||'尚未选择'
const catalogId=item=>typeof item==='string'?item:item.id||item.model||item.name||''
const filteredCatalog=computed(()=>catalog.value.filter(item=>`${catalogId(item)} ${item.name||''}`.toLowerCase().includes(catalogSearch.value.toLowerCase())))
const defaultModels=computed(()=>['text','image','video'].map(type=>{for(const channel of channels.value){const model=(channel.models||[]).find(model=>model.type===type&&model.is_default);if(model)return{type,channel,model}}return{type,channel:null,model:null}}))
function defaultUnavailable(model,channel=selected.value){if(!channel?.enabled)return '请先启用渠道';if(!model?.enabled)return '请先启用模型';const protocol=protocols.value.find(item=>item.id===model.protocol_id);if(!protocol||protocol.executable===false)return '此请求协议暂不可用';return ''}
async function setDefaultModel(model){
  if(workingModel.value||model.is_default||defaultUnavailable(model))return
  const channelId=selectedId.value,modelId=model.id
  workingModel.value=modelId;++loadSequence
  try{const result=await channelAPI.setDefault(channelId,modelId);if(!alive)return;if(result?.id!==modelId||result?.is_default!==true)throw Error('默认模型保存结果不匹配，请刷新确认。');await load();if(alive)toast.success(typeLabel(model.type)+'默认模型已更新；已有选择保持不变。')}
  catch(error){if(alive)toast.error(error.message)}finally{if(alive)workingModel.value=null}
}
function closeModel(){if(!savingModel.value)modelOpen.value=false}
function channelHost(value){try{return new URL(value).host}catch{return value||'尚未设置地址'}}
function objectJson(text,label){let value;try{value=JSON.parse(text||'{}')}catch{throw Error(`${label}不是有效 JSON。`)}if(!value||typeof value!=='object'||Array.isArray(value))throw Error(`${label}必须是 JSON 对象。`);return value}
async function load(){const sequence=++loadSequence;loading.value=true;error.value='';try{const [value,userRows]=await Promise.all([channelAPI.list(),platformUserAPI.list()]);const protocolRows=value.protocols||await channelAPI.protocols();if(!alive||sequence!==loadSequence)return;channels.value=value.channels||[];protocols.value=protocolRows;users.value=Array.isArray(userRows)?userRows:userRows.users||[];if(!routeError.value&&!channels.value.some(c=>c.id===selectedId.value))selectedId.value=channels.value[0]?.id||null;await applyRouteSelection()}catch(e){if(alive&&sequence===loadSequence)error.value=e.message}finally{if(alive&&sequence===loadSequence)loading.value=false}}
async function applyRouteSelection(){if(routeHandled)return;routeHandled=true;routeError.value='';linkedConfigId.value=null;const channelValue=String(route.query.channel_id||''),configValue=String(route.query.config_id||'');if(!channelValue&&!configValue)return;const channel=/^[1-9]\d*$/u.test(channelValue)?channels.value.find(item=>item.id===Number(channelValue)):null;const model=configValue&&/^[1-9]\d*$/u.test(configValue)?channel?.models?.find(item=>item.config_id===Number(configValue)):null;if(!channel||(configValue&&!model)){selectedId.value=null;routeError.value='链接中的渠道或模型不存在，或已移除。请核对后手动选择，不会替换为其他模型。';return}selectedId.value=channel.id;activeType.value='all';linkedConfigId.value=model?.config_id||null;if(model){await nextTick();if(alive)document.querySelector?.(`[data-config-id="${model.config_id}"]`)?.scrollIntoView?.({block:'center'})}}
function selectChannel(id){selectedId.value=id;linkedConfigId.value=null;routeError.value='';probeResult.value=null;activeType.value='all'}
watch(()=>String(route.query.channel_id||'')+'|'+String(route.query.config_id||''),()=>{routeHandled=false;routeError.value='';linkedConfigId.value=null;if(!loading.value)applyRouteSelection()})
