function closeChannel(){channelOpen.value=false;channelForm.api_key='';channelForm.headersText='';Object.keys(authValues).forEach(key=>delete authValues[key]);authClear.value=[]}
async function saveChannel(){saving.value=true;editorError.value='';try{const body={name:channelForm.name,base_url:channelForm.base_url,enabled:channelForm.enabled,...(channelForm.api_key?{api_key:channelForm.api_key}:{}),...(Object.values(authValues).some(value=>value!=='')?{auth_fields:Object.fromEntries(Object.entries(authValues).filter(([,value])=>value!==''))}:{}),...(authClear.value.length?{clear_auth_fields:authClear.value}:{}),...(channelForm.headersText.trim()?{headers:objectJson(channelForm.headersText,'请求头')}:{})};const result=channelForm.id?await channelAPI.update(channelForm.id,body):await channelAPI.create(body);selectedId.value=result.id||result.channel?.id||channelForm.id;closeChannel();await load();toast.success('渠道已保存')}catch(e){editorError.value=e.message}finally{saving.value=false}}
async function removeChannel(){if(!selected.value)return;const channel={...selected.value};if(!window.confirm(`删除渠道“${channel.name}”？该渠道及其模型将从配置和创作选项中移除，已提交任务与历史记录保留。`))return;try{await channelAPI.remove(channel.id);channels.value=channels.value.filter(item=>item.id!==channel.id);if(selectedId.value===channel.id)selectedId.value=channels.value[0]?.id||null;await load();toast.success('渠道已删除')}catch(e){toast.error(e.message)}}
async function probe(){const channelId=selectedId.value;testing.value=true;probeResult.value=null;try{const result=await channelAPI.test(channelId);if(!alive||selectedId.value!==channelId)return;probeResult.value=result;toast[result.ok===false?'warning':'success'](result.message||'连接检查完成')}catch(e){if(alive&&selectedId.value===channelId)probeResult.value={ok:false,message:e.message}}finally{if(alive)testing.value=false}}
function editModel(model,seed={}){modelError.value='';const type=model?.type||seed.type||(activeType.value==='all'?'text':activeType.value);Object.assign(modelForm,{id:model?.id||null,name:model?.name||seed.name||'',model:model?.model||seed.model||'',type,protocol_id:model?.protocol_id||seed.protocol_id||'',priority:model?.priority||0,enabled:model?model.enabled!==false:true,access:model?.access||'all',allowed_user_ids:[...(model?.allowed_user_ids||[])],capabilitiesText:JSON.stringify(model?.capabilities||seed.capabilities||{},null,2),defaultsText:JSON.stringify(model?.defaults||seed.defaults||{},null,2)});modelOpen.value=true}
function onModelTypeChange(){modelForm.protocol_id='';modelForm.capabilitiesText='{}';modelForm.defaultsText='{}'}
function onProtocolChange(){if(!modelForm.id&&selectedProtocol.value?.capabilities){let current={};try{current=objectJson(modelForm.capabilitiesText,'能力配置')}catch{}modelForm.capabilitiesText=JSON.stringify({...selectedProtocol.value.capabilities,...current},null,2)}}
async function saveModel(){if(savingModel.value)return;savingModel.value=true;modelError.value='';const channelId=selectedId.value;try{if(!selectedProtocol.value||selectedProtocol.value.type!==modelForm.type)throw Error('请选择当前模型类型对应的请求协议。');if(selectedProtocol.value.executable===false)throw Error('所选请求协议暂不可用，请选择可执行的协议。');const body={name:modelForm.name,model:modelForm.model,type:modelForm.type,protocol_id:modelForm.protocol_id,priority:Number(modelForm.priority)||0,enabled:modelForm.enabled,access:modelForm.access,allowed_user_ids:modelForm.access==='selected'?modelForm.allowed_user_ids:[],capabilities:objectJson(modelForm.capabilitiesText,'能力配置'),defaults:objectJson(modelForm.defaultsText,'默认参数')};if(modelForm.id)await channelAPI.updateModel(channelId,modelForm.id,body);else await channelAPI.createModel(channelId,body);modelOpen.value=false;await load();toast.success('模型已保存')}catch(e){modelError.value=e.message}finally{savingModel.value=false}}
