function escape(event){if(event.key==='Escape'){closeChannel();closeModel();catalogOpen.value=false;protocolOpen.value=false;pluginOpen.value=false}}
function choosePlugin(event){pluginFile.value=event.target.files?.[0]||null;pluginPreview.value=null;pluginError.value=''}
async function importPlugin(preview=true){if(!pluginFile.value||pluginBusy.value)return;pluginBusy.value=true;pluginError.value='';try{const result=await channelAPI.importPlugin(pluginFile.value,preview);pluginPreview.value=result;if(!preview){await load();toast.success('协议插件已导入');pluginFile.value=null}}catch(error){pluginError.value=error.message}finally{pluginBusy.value=false}}
